 /// Helper: convert a bitmap index to a frame (physical) address.
 pub open spec fn frame_addr_of(i: int) -> int {
     i * spec_page_size()
 }

 impl View for Inner {
     type V = FrameAllocView;

     closed spec fn view(&self) -> FrameAllocView {
         FrameAllocView {
             allocated_frames: Set::new(|addr: int|
