                     let i = addr / spec_page_size();
                     self.refcount@[i] as int
                 },
             ),
         }
     }
 }

 impl Inner {
     pub closed spec fn internal_inv(&self) -> bool
     {
         &&& self.bitmap.inv()
         &&& spec_page_size() > 0
