                 let reason: &str = "frame index not covered by the bitmap";
                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
             }
             match self.bitmap.test(index) {
                 Ok(false) => {},
                 Ok(true) => {
